    "question": "〔事例〕\nＥさん（34歳、女性、障害支援区分3）は、特別支援学校の高等部を卒業後、週2回、生活介護を利用しながら自宅で生活している。Ｅさんはアテトーゼ型（athetosis）の脳性麻痺｛のうせいまひ｝（cerebral palsy）で不随意運動があり、首を振る動作が見られる。\n食事は首の動きに合わせて、自助具を使って食べている。食事中は不随意運動が強く、食事が終わると、「首が痛い、しびれる」と言ってベッドに横になるときがある。\nまた、お茶を飲むときは取っ手つきのコップで飲んでいるが、コップを口元に運ぶまでにお茶がこぼれるようになってきた。日頃から自分のことは自分でやりたいと考えていて、お茶が上手に飲めなくなってきたことを気にしている。\nＥさんは、生活介護事業所で油絵を描くことを楽しみにしている。以前から隣町の油絵教室に通い技術を高めたいと話していた。そこでＥさんは、「自宅から油絵教室に通うときの介助をお願いするにはどうしたらよいか」と介護福祉職に相談した。\n\n<ruby>問題<rt>もんだい</rt></ruby>120 Ｅさんの<ruby>食事<rt>しょくじ</rt></ruby>の<ruby>様子<rt>ようす</rt></ruby>から，<ruby>今後<rt>こんご</rt></ruby>，<ruby>引き起<rt>ひきお</rt></ruby>こされる<ruby>可能性<rt>かのうせい</rt></ruby>が<ruby>高<rt>たか</rt></ruby>いと<ruby>考<rt>かんが</rt></ruby>えられる<ruby>二次障害<rt>にじしょうがい</rt></ruby>として，<ruby>最<rt>もっと</rt></ruby>も<ruby>適切<rt>てきせつ</rt></ruby>なものを1つ<ruby>選<rt>えら</rt></ruby>びなさい。",
